const samples = await IO.loadMNIST();
const sample = samples[31];
const coordinates = Array.from(sample, (_, i) => [(i % 28) / 27, 1 - Math.floor(i / 28) / 27]);
const trainXs = [];
const trainYs = [];
for (let i = 0; i < sample.length; i++) {
    const row = Math.floor(i / 28);
    const column = i % 28;
    if (row % 2 === 0 && column % 2 === 0) {
        trainXs.push(coordinates[i]);
        trainYs.push(sample[i]);
    }
}

let sigma = 0.06;
let lambda = 0.01;
const image = IO.paintMNIST([sample, new Float32Array(sample.length)]);
const fit = () => {
    const currentSigma = sigma;
    const gaussianKernel = (a, b) => {
        const dx = a[0] - b[0];
        const dy = a[1] - b[1];
        return Math.exp(-(dx * dx + dy * dy) / (2 * currentSigma * currentSigma));
    };
    const model = KernelRegression.new(trainXs, trainYs, {kernelFn: gaussianKernel, lambda}).fit();
    const reconstruction = Float32Array.from(coordinates, point => Math.max(0, Math.min(1, model.predict(point))));
    image.update([sample, reconstruction]);
};
fit();

let updateTimer;
const update = () => {
    clearTimeout(updateTimer);
    updateTimer = setTimeout(fit, 150);
};
const ui = IO.UI(
    {type: "canvas", value: () => image},
    {type: "slider", value: () => ({
        title: "Sigma:", min: 0.02, max: 0.2, step: 0.01, value: sigma,
        onChange: value => { sigma = value; update(); },
    })},
    {type: "slider", value: () => ({
        title: "Lambda:", min: 0.01, max: 0.5, step: 0.01, value: lambda,
        onChange: value => { lambda = value; update(); },
    })},
);
ui;
